/* Multiply the matrix A by the matrix B. Store the results in the matrix C.
   A is an MxK matrix, B is a KxN matrix, and C is a MxN matrix. The matrices are stored in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[[1, -1, 2], [0, -2, 1]] B=[[4, 1], [-1, 0], [2, 2]]
   output: C=[[9, 5], [4, 2]]
*/
void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {

generated_output:
void gemm(std::vector<double> const& A,
          std::vector<double> const& B,
          std::vector<double> &C,
          std::size_t M, std::size_t K, std::size_t N)
{
    if (A.size() != M * K || B.size() != K * N) {
        throw std::invalid_argument("gemm: input sizes do not match dimensions");
    }

    if (C.size() != M * N) {
        C.resize(M * N);
    }

    // Parallelize over all output elements
    hpx::for_loop(hpx::execution::par, std::size_t(0), M * N,
        [&](std::size_t idx) {
            std::size_t i = idx / N;   // row in C
            std::size_t j = idx % N;   // column in C

            double sum = 0.0;
            std::size_t arow = i * K;  // start of row i in A
            for (std::size_t k = 0; k < K; ++k) {
                sum += A[arow + k] * B[k * N + j];
            }
            C[idx] = sum;
        });
}

