void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C,
          size_t M, size_t K, size_t N)
{
    if (A.size() != M * K || B.size() != K * N)
        throw std::invalid_argument("gemm: input sizes do not match dimensions");

    if (C.size() != M * N) C.assign(M * N, 0.0);
    else std::fill(C.begin(), C.end(), 0.0);

    auto row_first = hpx::make_counting_iterator<std::size_t>(0);
    auto row_last  = hpx::make_counting_iterator<std::size_t>(M);

    hpx::for_each(hpx::execution::par, row_first, row_last, [&](std::size_t i) {
        std::size_t arow = i * K;
        std::size_t crow = i * N;
        for (std::size_t j = 0; j < N; ++j) {
            double sum = 0.0;
            for (std::size_t k = 0; k < K; ++k) {
                sum += A[arow + k] * B[k * N + j];
            }
            C[crow + j] = sum;
        }
    });
}

