/* Multiply the matrix A by the matrix B. Store the results in the matrix C.
   A is an MxK matrix, B is a KxN matrix, and C is a MxN matrix. The matrices are stored in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[[1, -1, 2], [0, -2, 1]] B=[[4, 1], [-1, 0], [2, 2]]
   output: C=[[9, 5], [4, 2]]
*/
void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {

generated_output:
void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {
    if (A.size() != M * K || B.size() != K * N || C.size() != M * N) {
        throw std::invalid_argument("gemm: size mismatch");
    }

    auto first = hpx::make_counting_iterator<std::size_t>(0);
    auto last  = hpx::make_counting_iterator<std::size_t>(M * N);

    hpx::ranges::for_each(hpx::execution::par, first, last, [&](std::size_t idx) {
        const std::size_t i = idx / N;
        const std::size_t j = idx % N;

        double sum = 0.0;
        const std::size_t arow = i * K;
        std::size_t bidx = j;

        for (std::size_t k = 0; k < K; ++k) {
            sum += A[arow + k] * B[bidx];
            bidx += N; // move down column j in B
        }

        C[idx] = sum;
    });
}

