void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {
    if (A.size() != M * K || B.size() != K * N || C.size() != M * N) {
        throw std::invalid_argument("gemm: size mismatch");
    }
    if (M == 0 || K == 0 || N == 0) return;

    hpx::for_loop(hpx::execution::par, std::size_t(0), M * N, [&](std::size_t idx) {
        std::size_t i = idx / N;   // row in C
        std::size_t j = idx % N;   // column in C

        double sum = 0.0;
        std::size_t arow = i * K;
        for (std::size_t k = 0; k < K; ++k) {
            sum += A[arow + k] * B[k * N + j];
        }
        C[idx] = sum;
    });
}

