void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {

#include <hpx/hpx_main.hpp>

/* Multiply the matrix A by the matrix B. Store the results in the matrix C.
   A is an MxK matrix, B is a KxN matrix, and C is a MxN matrix. The matrices are stored in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[[1, -1, 2], [0, -2, 1]] B=[[4, 1], [-1, 0], [2, 2]]
   output: C=[[9, 5], [4, 2]]
*/
void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {

generated_output:
void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {
    if (A.size() != M * K || B.size() != K * N || C.size() != M * N) {
        throw std::invalid_argument("gemm: input sizes do not match provided dimensions");
    }

    // Parallelize over rows of C (and A). Each iteration writes to a distinct row of C.
    hpx::for_loop(hpx::execution::par, std::size_t(0), M, [&](std::size_t i) {
        double* Ci = C.data() + i * N;

        // Initialize row i of C to zero (handles K == 0 case as well)
        std::fill(Ci, Ci + N, 0.0);

        // Accumulate A(i, k) * B(k, :)
        for (std::size_t k = 0; k < K; ++k) {
            double const aik = A[i * K + k];
            double const* Bk = B.data() + k * N;  // row k of B
            for (std::size_t j = 0; j < N; ++j) {
                Ci[j] += aik * Bk[j];
            }
        }
    });
}

