generated_output:
void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {
    if (A.size() != M * K || B.size() != K * N) {
        throw std::invalid_argument("Invalid matrix dimensions");
    }

    C.assign(M * N, 0.0);

    // Parallelize over rows of C (and A)
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        const size_t a_row = i * K;
        const size_t c_row = i * N;

        // Accumulate C[i, :] = sum_k A[i, k] * B[k, :]
        for (size_t k = 0; k < K; ++k) {
            const double aik = A[a_row + k];
            const size_t b_row = k * N;

            // Walk contiguous rows of B and C for good cache locality
            for (size_t j = 0; j < N; ++j) {
                C[c_row + j] += aik * B[b_row + j];
            }
        }
    });
}

