void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {
    if (A.size() != M * K || B.size() != K * N) {
        throw std::invalid_argument("gemm: input sizes do not match given dimensions");
    }

    if (C.size() != M * N) {
        C.assign(M * N, 0.0);
    } else {
        std::fill(C.begin(), C.end(), 0.0);
    }

    auto first = hpx::util::make_counting_iterator<std::size_t>(0);
    auto last  = hpx::util::make_counting_iterator<std::size_t>(M * N);

    // Optionally tune chunk size for better cache locality
    auto exec = hpx::execution::par.with(hpx::execution::static_chunk_size(64));

    hpx::for_each(exec, first, last, [&](std::size_t idx) {
        std::size_t i = idx / N; // row in C
        std::size_t j = idx % N; // column in C

        double sum = 0.0;
        std::size_t a_row = i * K;
        for (std::size_t k = 0; k < K; ++k) {
            sum += A[a_row + k] * B[k * N + j];
        }
        C[idx] = sum; // C[i * N + j]
    });
}

