            const double* btcol = &BT[j * K];  // contiguous K elements
            double sum = 0.0;
            for (std::size_t k = 0; k < K; ++k) {
                sum += arow[k] * btcol[k];
            }
            C[i * N + j] = sum;
        }
    });
}

