   output: C=[[9, 5], [4, 2]]
*/
void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {

generated_output:
void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C,
          size_t M, size_t K, size_t N)
{
    if (A.size() != M * K || B.size() != K * N || C.size() != M * N) {
        throw std::invalid_argument("gemm: mismatched matrix sizes");
    }

    hpx::for_loop(hpx::execution::par, std::size_t(0), M, [&](std::size_t i) {
        const std::size_t arow = i * K;
        const std::size_t crow = i * N;

        for (std::size_t j = 0; j < N; ++j) {
            double sum = 0.0;
            for (std::size_t k = 0; k < K; ++k) {
                sum += A[arow + k] * B[k * N + j];
            }
            C[crow + j] = sum;
        }
    });
}

