generated_output:
void axpy(double alpha, std::vector<double> const& x, std::vector<double> const& y, std::vector<double> &z) {
    if (x.size() != y.size()) {
        throw std::invalid_argument("axpy: x and y must have the same length");
    }

    z.resize(x.size());

    hpx::transform(hpx::execution::par_unseq,
                   x.begin(), x.end(), y.begin(), z.begin(),
                   [alpha](double xi, double yi) noexcept {
                       return alpha * xi + yi;
                   });
}

