generated_output:
void axpy(double alpha, std::vector<double> const& x, std::vector<double> const& y, std::vector<double> &z) {
    if (x.size() != y.size())
        throw std::invalid_argument("x and y must have the same size");

    const std::size_t n = x.size();
    z.resize(n);

    auto compute = [alpha](double xi, double yi) noexcept {
        return std::fma(alpha, xi, yi); // alpha*xi + yi, fused if available
    };

    // Guard against aliasing (z sharing storage with x or y) when running in parallel
    if (n != 0 && (z.data() == x.data() || z.data() == y.data())) {
        std::vector<double> tmp(n);
        hpx::transform(hpx::execution::par_unseq,
                       x.begin(), x.end(),
                       y.begin(),
                       tmp.begin(),
                       compute);
        z.swap(tmp);
    } else {
        hpx::transform(hpx::execution::par_unseq,
                       x.begin(), x.end(),
                       y.begin(),
                       z.begin(),
                       compute);
    }
}

