   Use HPX to compute in parallel. Assume HPX has already been initialized. 
   Example:

   input: A=[[1, -1, 2], [0, -3, 1]] x=[2, 1, 0]
   output: y=[1, -3]
*/
void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {

generated_output:
void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double>& y, size_t M, size_t N)
{
    if (A.size() != M * N) throw std::invalid_argument("gemv: A size != M*N");
    if (x.size() != N)     throw std::invalid_argument("gemv: x size != N");

    y.assign(M, 0.0);  // size and zero-init

    if (M == 0 || N == 0) return;

    hpx::for_loop(hpx::execution::par, size_t(0), M,
        [&](size_t i)
        {
            double sum = 0.0;
            size_t row_offset = i * N;

            // sequential dot product for row i
            for (size_t j = 0; j < N; ++j)
                sum += A[row_offset + j] * x[j];

            y[i] = sum;
        });
}

