void gemv(std::vector<double> const& A,
          std::vector<double> const& x,
          std::vector<double> &y,
          size_t M, size_t N)
{
    if (A.size() != M * N) throw std::invalid_argument("A size != M*N");
    if (x.size() != N)     throw std::invalid_argument("x size != N");

    y.resize(M);

    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        const double* row = A.data() + i * N;
        double sum = 0.0;
        for (size_t j = 0; j < N; ++j)
            sum += row[j] * x[j];
        y[i] = sum;
    });
}

