void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
    if (A.size() != M * N) throw std::invalid_argument("A size != M*N");
    if (x.size() != N) throw std::invalid_argument("x size != N");

    if (y.size() != M) y.resize(M);

    // Parallelize over rows
    hpx::for_loop(hpx::execution::par, std::size_t(0), M, [&](std::size_t i) {
