    // Row-major: A[i*N + j]
    hpx::for_each(hpx::execution::par, first, last,
        [&](std::size_t i) {
            const double* ai = A.data() + i * N;
            y[i] = std::inner_product(ai, ai + N, x.data(), 0.0);
        });
}

